    slug: "becs-co2-ph-control", name: "BECSys CO2 pH Feed System", manufacturer: "becs", category: "chemical-delivery-chlorination", subcategory: "pH control", status: "published", availability: "confirmed",
    aliases: ["BECS CO2 feeder", "carbon dioxide pH control", "CO2 feed"], keywords: ["acid-free pH control", "carbonic acid", "pH feed"],
    headline: "Carbon dioxide pH control that lowers pH without storing acid in the equipment room",
    shortDescription: "BECS Technology CO2 feed system in 5–50 and 20–200 SCFH sizes with diffuser or Venturi eductor; NSF/ANSI 50 listed per BECS.",
    overview: ["Carbon dioxide feed lowers pH by forming carbonic acid in the water rather than by dosing mineral acid. Operators like it because there is no acid to handle or store; the trade-off is that CO2 raises total alkalinity over time, so alkalinity has to be watched. BECS offers a CO2 feed system sized in two ranges, with a diffuser or Venturi eductor, regulator, heater, and cylinder switchover options, controlled by the BECSys controller's pH output."],
    fit: { yes: ["Facilities that want to eliminate acid handling", "Pools with adequate alkalinity management", "BECSys installations adding pH control"], no: ["Pools with chronically high alkalinity, where CO2 compounds the problem"] },
    problems: ["improve-chemical-safety", "stabilize-water-chemistry"],
    applications: ["Institutional pools with BECSys controllers", "Therapy pools where acid storage is a concern"],
    facilities: ["k12-schools", "colleges-universities", "ymca-community", "healthcare-rehabilitation", "municipal-aquatic-centers", "hotels-resorts-hospitality"],
    projectTypes: ["new-construction", "retrofit", "replacement"],
    features: ["Two size ranges: 5–50 SCFH and 20–200 SCFH", "Diffuser or Venturi eductor injection", "Regulator, heater, and cylinder switchover options", "NSF/ANSI 50 listed per BECS"],
    benefits: ["No mineral acid stored or handled", "Smooth pH control under the BECSys controller", "Fewer corrosive-chemical incidents in the equipment room"],
    specs: [{ k: "Capacity", v: "5–50 SCFH or 20–200 SCFH", src: "BECS SLS-6107-B" }, { k: "Injection", v: "Diffuser or Venturi eductor", src: "BECS SLS-6107-B" }, { k: "Listing", v: "NSF/ANSI 50 (CCS-14530) per BECS", src: "BECS SLS-6107-B" }, { k: "Warranty (manufacturer)", v: "1 year per BECS brochure", src: "BECS SLS-6107-B" }],
    prerequisites: ["BECSys controller with pH output", "CO2 cylinder or bulk supply location and ventilation", "Alkalinity monitoring plan"],
    retrofit: ["Commonly replaces acid metering pumps during a controller upgrade", "Watch total alkalinity trend after conversion"],
    integrations: [{ name: "BECSys3/5/7", note: "Controlled from the controller's pH output.", status: "verified" }],
    services: ["Specification and installation with the controller", "Commissioning and operator training"],
    support: ["Service and parts", "BECS warranty coordination"],
