    models: [{ name: "Alkalinity Up", fit: "Granular total alkalinity increaser. Manufacturer says it raises total alkalinity and acts as a buffer to prevent pH bounce, staining, and corrosion.", specs: [{ k: "Form", v: "Granular", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "5 lb, 10 lb, 25 lb", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }, { name: "pH Up", fit: "Granular pH increaser. Manufacturer says it raises pH with minimal effect on overall alkalinity and reduces eye and nose irritation.", specs: [{ k: "Form", v: "Granular", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "2 lb, 5 lb, 10 lb, 25 lb", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }, { name: "pH Down", fit: "Granular dry acid pH decreaser. Manufacturer says it lowers pH slowly and effectively, is more convenient than liquid acid, and helps prevent scale build-up.", specs: [{ k: "Form", v: "Granular dry acid", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "2.5 lb, 6 lb", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }, { name: "Calcium Elevator", fit: "Granular calcium hardness increaser. Manufacturer says it raises calcium hardness to the recommended level and helps protect surfaces, plumbing, and equipment from corrosive conditions.", specs: [{ k: "Form", v: "Granular", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "4 lb, 8 lb, 25 lb", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }, { name: "Clor Save", fit: "Granular chlorine stabilizer. Manufacturer says it raises stabilizer (CYA) to the recommended level, reduces chlorine loss from UV, and dissolves completely when applied as directed.", specs: [{ k: "Form", v: "Granular stabilizer (CYA)", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "1.75 lb, 4 lb, 7 lb, 25 lb", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }, { name: "Liquid Clor Save", fit: "Liquid chlorine stabilizer. Manufacturer says it raises stabilizer (CYA) to the recommended level, reduces chlorine loss from sunlight, and rapidly disperses.", specs: [{ k: "Form", v: "Liquid stabilizer (CYA)", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Package sizes", v: "1 gallon", src: "https://www.ezclorchemicals.com/products/balancers" }, { k: "Product page", v: "https://www.ezclorchemicals.com/products/balancers", src: "https://www.ezclorchemicals.com/products/balancers" }] }],
