    specs: [{ k: "Horsepower", v: "5-20 HP, 3500/3450 RPM", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Flow", v: "to 740 GPM", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Ports", v: "6 in ANSI 125 lb flanged suction on strainer (5 in less strainer); 4 in ANSI 125 lb flanged discharge", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Materials", v: "Bronze CA 84400 volute, adapter and strainer pot; bronze CA 83600 impeller; enamel-coated cast iron CL30 foot; stainless steel basket; 303 SS motor shaft", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Electrical", v: "Three-phase 208/220-440 and 200/208 V; single-phase 5 and 7.5 HP at 200-208 or 230 V, 10 HP at 230 V; 50/60 Hz; 575 V on request", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Motor", v: "JM open drip-proof, continuous duty, lubricated double-sealed ball bearings; external thermal overload required", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Limits", v: "104 F liquid and ambient; 50 psi; seal rated to 150 F", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Certification", v: "Engineering spec requires NSF Standard 50 certification; single-phase 7.5 HP 200/208 V models footnoted as not NSF listed", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }, { k: "Warranty", v: "One-year limited warranty", src: "https://www.pentair.com/content/dam/extranet/nam/pentair-pool/commercial/pumps/c-series/c-series-commercial-bronze-pool-pump-brochure.pdf" }],
    prerequisites: ["External thermal overload protector on all models", "Cool, dry, well-vented location away from heaters and chemical storage; 12 in clearance behind motor", "Flanged 6 in / 4 in piping connections"], retrofit: ["Pentair's EQ Series is stated to be a drop-in replacement for C Series pumps, giving a plastic alternative for the same footprint", "Available with or without hair-and-lint strainer to match existing strainer arrangements"], integrations: [],
