    docs: [{ title: "Surge and Balance Tanks (product page)", type: "Product page", href: "https://mermade.com/product/surge-and-balance-tanks/", fileType: "Web", status: "linked" }, { title: "Surge and balance tank brochure with dimensional and capacity chart data", type: "Brochure", href: "https://mermade.com/wp-content/uploads/sites/4/2022/03/mermade-filter-surge-balance-tank-brochure-dimensional-capacity-and-chart-data.pdf", fileType: "PDF", status: "linked" }, { title: "Vertical fiberglass surge tank drawing T-14396", type: "Specification sheet", href: "https://mermade.com/wp-content/uploads/sites/4/2024/01/mer-made-filter-vertical-fiberglass-surge-and-balance-tanks.pdf", fileType: "PDF", status: "linked" }, { title: "Horizontal fiberglass surge tank drawing T-14395", type: "Specification sheet", href: "https://mermade.com/wp-content/uploads/sites/4/2024/01/mer-made-filter-horizontal-fiberglass-surge-and-balance-tanks.pdf", fileType: "PDF", status: "linked" }], faqs: [{ q: "What is the difference between a surge tank and a balance tank?", a: "Per Mer-Made, a surge tank provides storage capacity above the main drain centerline for water displaced by swimmers, sized to code (commonly one gallon per sq. ft. of pool surface). Balance or collector tanks are smaller tanks that accept main drain and gutter water with an outlet to pump suction and usually do not meet surge capacity requirements." }, { q: "Can the tank be buried?", a: "The manufacturer states the standard horizontal tank must not be used for buried service; tanks are designed for installation below pool deck level in an equipment space." }], related: [], specifiedWith: [], relatedSolutions: ["modernize-aging-equipment-room", "find-replacement-equipment"],
