    sourceUrls: ["https://mermade.com/product/surge-and-balance-tanks/", "https://mermade.com/wp-content/uploads/sites/4/2022/03/mermade-filter-surge-balance-tank-brochure-dimensional-capacity-and-chart-data.pdf", "https://mermade.com/wp-content/uploads/sites/4/2024/01/mer-made-filter-vertical-fiberglass-surge-and-balance-tanks.pdf", "https://mermade.com/wp-content/uploads/sites/4/2024/01/mer-made-filter-horizontal-fiberglass-surge-and-balance-tanks.pdf"], claimStatus: "verified", lastVerified: "2026-09-26", ownerApproved: false,
